update pms_deliverable
   set deliv_nm = #{delivNm}, required_yn = #{requiredYn}, form_doc_no = #{formDocNo}, owner_user_id = #{ownerUserId},
       due_date = #{dueDate}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where deliv_id = #{id} and row_ver = #{rowVer}

update pms_deliverable
   set status = 'SUBMITTED', ref_type = 'FILE', ref_id = #{fileId}, sub_cnt = sub_cnt + 1,
       submitted_by = #{by}, submitted_at = now(), decided_by = null, decided_at = null, decision_note = null,
       waive_reason = null, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where deliv_id = #{id} and row_ver = #{rowVer}

update pms_deliverable
   set status = 'SUBMITTED', ref_type = #{refType}, ref_id = #{refId}, sub_cnt = sub_cnt + 1,
       submitted_by = #{by}, submitted_at = now(), decided_by = null, decided_at = null, decision_note = null,
       waive_reason = null, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where deliv_id = #{id} and row_ver = #{rowVer}

mapper.select:
select count(*) from pms_deliverable d
 where d.task_id = #{taskId}
   and (d.status <> 'NONE' or d.sub_cnt > 0 or exists (select 1 from pms_deliverable_hist h where h.deliv_id = d.deliv_id))

select 
  from pms_gate_review r left join apr_request a on a.apr_id = r.apr_id
 where r.review_id = #{id}

mapper.update:
update pms_gate_review
   set status = 'DRAFT', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where review_id = #{id} and status = 'IN_APPROVAL'

update pms_gate_review
   set status = 'CANCELLED', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where review_id = #{id} and row_ver = #{rowVer} and status = 'DRAFT'
